import React, { useEffect, useRef, useState, useContext } from "react";
import { AuthContext } from "../Context/AuthContext";
import { eraseLine } from "../utils/erase";

function CanvasBoard({ socket }) {
  const canvasRef = useRef(null);
  const ctxRef = useRef(null);
  const { user } = useContext(AuthContext);

  const [drawing, setDrawing] = useState(false);
  const [lastPos, setLastPos] = useState(null);
  const [currentTool, setCurrentTool] = useState("pen");

  useEffect(() => {
    const canvas = canvasRef.current;
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight - 80;

    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "white";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = "black";
    ctx.lineWidth = 2;
    ctxRef.current = ctx;
  }, []);

  const startDrawing = (e) => {
    if (user.role === "viewer") return;
    setDrawing(true);
    const { offsetX, offsetY } = e.nativeEvent;
    setLastPos({ x: offsetX, y: offsetY });

    const ctx = ctxRef.current;
    ctx.beginPath();
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.moveTo(offsetX, offsetY);
  };

  const draw = (e) => {
    if (!drawing) return;

    const { offsetX, offsetY } = e.nativeEvent;
    const ctx = ctxRef.current;
    if (!lastPos) return;

    if (currentTool === "eraser") {
      eraseLine(ctx, lastPos.x, lastPos.y, offsetX, offsetY);
    } else {
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "black";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(lastPos.x, lastPos.y);
      ctx.lineTo(offsetX, offsetY);
      ctx.stroke();
      ctx.closePath();
    }

    // Emit the draw data to server, which will send to all clients
    socket.emit("draw", {
      x0: lastPos.x,
      y0: lastPos.y,
      x1: offsetX,
      y1: offsetY,
      tool: currentTool,
    });

    // Update last position to current for smooth drawing
    setLastPos({ x: offsetX, y: offsetY });
  };

  const stopDrawing = () => {
    setDrawing(false);
    setLastPos(null);
    if (ctxRef.current) ctxRef.current.closePath();
  };

  useEffect(() => {
    // Listener for draw events from server for all clients including self
    socket.on("draw", (data) => {
      const ctx = ctxRef.current;
      if (!ctx) return;

      if (data.tool === "eraser") {
        eraseLine(ctx, data.x0, data.y0, data.x1, data.y1);
      } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.strokeStyle = "black";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(data.x0, data.y0);
        ctx.lineTo(data.x1, data.y1);
        ctx.stroke();
        ctx.closePath();
      }
    });

    // Cleanup on component unmount
    return () => {
      socket.off("draw");
    };
  }, [socket]);

  return (
    <div>
      <div style={{ marginBottom: "10px" }}>
        <button
          onClick={() => setCurrentTool("pen")}
          style={{
            backgroundColor: currentTool === "pen" ? "#007bff" : "#ccc",
            color: "white",
            marginRight: "10px",
            padding: "8px 16px",
            border: "none",
            cursor: "pointer",
          }}
        >
          Pen
        </button>
        <button
          onClick={() => setCurrentTool("eraser")}
          style={{
            backgroundColor: currentTool === "eraser" ? "#007bff" : "#ccc",
            color: "white",
            padding: "8px 16px",
            border: "none",
            cursor: "pointer",
          }}
        >
          Eraser
        </button>
      </div>
      <canvas
        ref={canvasRef}
        className="border"
        onMouseDown={startDrawing}
        onMouseMove={draw}
        onMouseUp={stopDrawing}
        onMouseLeave={stopDrawing}
        style={{
          backgroundColor: "white",
          cursor: currentTool === "eraser" ? "crosshair" : "pointer",
        }}
      />
    </div>
  );
}

export default CanvasBoard;
